// Drives `scripts/eject-examples.ts`. Paths are repo-root-relative.
export const manifest = {
  // Purely-example files/dirs — removed wholesale.
  remove: [
    "src/features/guestbook",
    "src/app/[locale]/guestbook",
    "src/app/api/health",
    "src/core/db/schema/guestbook.ts",
    // Generated by `db:types` in the example's schema step; carries a stale `guestbook`
    // type after eject. Deleted to match the pre-example baseline (regenerate via
    // `pnpm db:types` once you add your own schema). Nothing imports it.
    "src/core/db/supabase-types.ts",
    "src/core/test/ids/app-ids.ts",
    "src/core/test/ids/__tests__/app-ids.test.ts",
    "supabase/migrations/0000_guestbook.sql",
    "supabase/migrations/0001_rls_guestbook.sql",
    "supabase/migrations/meta",
  ],
  // Shared files the slice wired into — restored from committed pristine copies.
  // key = real path, value = pristine source under scripts/eject/pristine/.
  // `src/core/db/index.ts` is NOT restored: its `export *` lines are eject-invariant
  // (the sub-barrels revert to placeholders, but the forwarding lines don't change),
  // and `queries/index.ts` is already its own bare placeholder now that the guestbook
  // query moved to the feature.
  restore: {
    "src/core/db/schema/index.ts": "scripts/eject/pristine/src/core/db/schema/index.ts",
    "src/core/test/index.ts": "scripts/eject/pristine/src/core/test/index.ts",
  },
  // JSON keys to drop (preserves any other keys the forker added).
  jsonKeyRemovals: [{ file: "messages/en.json", key: "guestbook" }],
  // Removed only with --clean-self, plus the "eject:examples" package.json script.
  selfCleanup: ["scripts/eject", "scripts/eject-examples.ts"],
} as const;
